CREATE TYPE "SafetyReportConversationRole" AS ENUM ('REPORTER','REPORTED_PARTICIPANT');CREATE TYPE "SafetyReportMessageAuthorType" AS ENUM ('ADMINISTRATOR','PARTICIPANT');
CREATE TABLE "SafetyReportConversation" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"safetyReportId" UUID NOT NULL,"participantRole" "SafetyReportConversationRole" NOT NULL,"participantId" TEXT NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SafetyReportConversation_pkey" PRIMARY KEY("id"));
CREATE TABLE "SafetyReportMessage" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"conversationId" UUID NOT NULL,"authorType" "SafetyReportMessageAuthorType" NOT NULL,"administratorId" TEXT,"participantId" TEXT,"body" VARCHAR(2000) NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SafetyReportMessage_pkey" PRIMARY KEY("id"),CONSTRAINT "SafetyReportMessage_author_check" CHECK (("authorType"='ADMINISTRATOR' AND "administratorId" IS NOT NULL AND "participantId" IS NULL) OR ("authorType"='PARTICIPANT' AND "participantId" IS NOT NULL AND "administratorId" IS NULL)),CONSTRAINT "SafetyReportMessage_body_check" CHECK ("body"=btrim("body") AND char_length("body") BETWEEN 1 AND 2000));
CREATE UNIQUE INDEX "SafetyReportConversation_safetyReportId_participantRole_key" ON "SafetyReportConversation"("safetyReportId","participantRole");CREATE INDEX "SafetyReportConversation_participantId_createdAt_id_idx" ON "SafetyReportConversation"("participantId","createdAt","id");CREATE INDEX "SafetyReportMessage_conversationId_createdAt_id_idx" ON "SafetyReportMessage"("conversationId","createdAt","id");
ALTER TABLE "SafetyReportConversation" ADD CONSTRAINT "SafetyReportConversation_safetyReportId_fkey" FOREIGN KEY("safetyReportId") REFERENCES "SafetyReport"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportConversation" ADD CONSTRAINT "SafetyReportConversation_participantId_fkey" FOREIGN KEY("participantId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SafetyReportMessage" ADD CONSTRAINT "SafetyReportMessage_conversationId_fkey" FOREIGN KEY("conversationId") REFERENCES "SafetyReportConversation"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportMessage" ADD CONSTRAINT "SafetyReportMessage_administratorId_fkey" FOREIGN KEY("administratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportMessage" ADD CONSTRAINT "SafetyReportMessage_participantId_fkey" FOREIGN KEY("participantId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
